  const r = spawnSync(BIN, ['--a', val], {encoding:'buffer', maxBuffer: 100*1024*1024});
  return {out: r.stdout, err: r.stderr, code: r.status};
}
module.exports = {run};
if (require.main === module) {
  const v = process.argv[2];
  const r = run(v);
  console.log('exit', r.code);
  console.log('stdout hex', r.out.toString('hex'));
  console.log('stdout utf8', JSON.stringify(r.out.toString('utf8')));
  if (r.err && r.err.length) console.log('stderr', r.err.toString('utf8'));
}
